{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Tetrabenazine, a benzoquinolizine CNS drug with methoxy and tertiary amine groups, has very low mean oral systemic availability (0.049 ± 0.032) in patients, but its extensive first-pass metabolism and different scaffold limit transfer to galantamine.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C22"],
      "claim": "Almorexant, a tetrahydroisoquinoline orexin antagonist, has absolute oral bioavailability of about 11.2%, but its poor absorption/first-pass profile and different core structure do not transfer to galantamine.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C08"],
      "claim": "Physostigmine, another acetylcholinesterase inhibitor alkaloid, has poor oral bioavailability, but its hydrolyzable carbamate and distinct physicochemical properties make it a poor model for galantamine.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C02"],
      "claim": "A thienorphine-like morphinan (ThH) has very low oral bioavailability, but its opioid scaffold and substituents differ substantially from galantamine, so this low-F evidence does not transfer.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query molecule is galantamine, a well-absorbed tertiary alkaloid acetylcholinesterase inhibitor with established absolute oral bioavailability of approximately 90% in humans, far above the 20% threshold. The supplied low-bioavailability records are from structurally and mechanistically distinct compounds and do not override the recognized high oral bioavailability of galantamine.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for galantamine is present in the provided experimental records.",
    "No human pharmacokinetic data for galantamine under fasted conditions are included in the evidence set.",
    "All provided records are low-F examples from other chemical classes; none establish low F for galantamine."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

